function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}

function updatePlayer(dt){
  const forward=keys.w||keys.arrowup;
  const brake=keys.s||keys.arrowdown;
  const left=keys.a||keys.arrowleft;
  const right=keys.d||keys.arrowright;
  const handbrake=keys[' '] || keys.space;

  if(forward) player.speed+=210*dt;
  if(brake){
    if(player.speed>10) player.speed-=300*dt;
    else player.speed-=155*dt;
  }
  if(!forward&&!brake) player.speed*=Math.pow(.985,dt*60);

  const boosting=(keys.shift||keys.shiftleft)&&player.nitro>0&&forward&&player.speed>20;
  if(boosting){player.speed+=240*dt;player.nitro-=24*dt;player.drift=Math.min(1,player.drift+dt*2)}
  else{player.nitro=Math.min(100,player.nitro+8*dt);player.drift=Math.max(0,player.drift-dt*2)}

  player.speed=clamp(player.speed,-95,boosting?330:245);
  const steering=(left?-1:0)+(right?1:0);
  if(Math.abs(player.speed)>4){
    const steeringScale=clamp(Math.abs(player.speed)/130,.28,1);
    player.angle+=steering*dt*(handbrake?2.35:1.35)*steeringScale*(player.speed>=0?1:-.55);
  }

  player.x+=Math.cos(player.angle)*player.speed*dt;
  player.y+=Math.sin(player.angle)*player.speed*dt;
  player.x=clamp(player.x,22,W-22);player.y=clamp(player.y,22,H-22);

  if(handbrake&&Math.abs(player.speed)>75){
    player.drift=Math.min(1,player.drift+dt*3);
    particles.push({x:player.x-Math.cos(player.angle)*20,y:player.y-Math.sin(player.angle)*20,life:.65,color:'#c9c5ab'});
  }

  let onRoad=false;
  for(const x of roadX)if(Math.abs(player.x-x)<roadWidth/2+8)onRoad=true;
  for(const y of roadY)if(Math.abs(player.y-y)<roadWidth/2+8)onRoad=true;
  if(!onRoad){
    player.speed*=Math.pow(.965,dt*60);
    if(Math.abs(player.speed)>25&&Math.random()<.18)particles.push({x:player.x,y:player.y,life:.4,color:'#9d8d62'});
  }

  for(const b of buildings){
    if(player.x>b.x-18&&player.x<b.x+b.w+18&&player.y>b.y-18&&player.y<b.y+b.h+18){
      player.x-=Math.cos(player.angle)*player.speed*dt*1.8;
      player.y-=Math.sin(player.angle)*player.speed*dt*1.8;
      player.speed*=-.18;
    }
  }

  if(player.heat>0&&!active)player.heat=Math.max(0,player.heat-dt*.018);
}

function updateTraffic(dt){
  for(const car of traffic){
    car.x+=car.horizontal?car.dir*car.speed*dt:0;
    car.y+=!car.horizontal?car.dir*car.speed*dt:0;
    car.angle=car.horizontal?(car.dir>0?0:Math.PI):(car.dir>0?Math.PI/2:-Math.PI/2);
    if(car.x<-40)car.x=W+40;if(car.x>W+40)car.x=-40;
    if(car.y<-40)car.y=H+40;if(car.y>H+40)car.y=-40;
    if(distance(player,car)<30){
      player.speed*=.82;player.heat=Math.min(5,player.heat+.22);
      car.dir*=-1;
    }
  }
}

function updatePolice(dt){
  if(player.heat>=1.2){
